import {esc} from './views.mjs';
import {toDisplay,isCustomExercise} from './core.mjs';
export function routineEditorView(editor,state){const unit=state.settings.unit,ex=id=>state.exercises.find(e=>e.id===id);return `<section aria-label="Routine editor"><div class="editor-toolbar"><button class="quiet" data-action="cancel-routine">Back</button><button class="primary" data-action="commit-routine">Save routine</button></div><p class="eyebrow">BUILD YOUR NEXT SESSION</p><h1>${state.routines.some(r=>r.id===editor.id)?'Edit routine.':'Your next routine.'}</h1><label class="editor-name">Routine name<input aria-label="Routine name" data-routine-name maxlength="120" placeholder="e.g. Push day" value="${esc(editor.name)}" required></label><p class="help">Set your targets once. Leave weight blank to fill it in at the gym. Changes here won’t affect workouts already started.</p>${editor.entries.map((e,index)=>{const exercise=ex(e.exerciseId);return `<section class="exercise template-exercise"><div class="exercise-title"><div class="grow"><p class="eyebrow">${String(index+1).padStart(2,'0')} / ${esc(exercise.muscle||'Other')}${e.group?' · SUPERSET':''}</p><h3>${esc(exercise.name)}</h3></div><button class="quiet" data-entry-options="${e.id}" aria-label="Options for ${esc(exercise.name)}">•••</button></div><div class="template-order"><button class="quiet" data-move="${e.id}" data-direction="-1" aria-label="Move ${esc(exercise.name)} up" ${index===0?'disabled':''}>Up</button><button class="quiet" data-move="${e.id}" data-direction="1" aria-label="Move ${esc(exercise.name)} down" ${index===editor.entries.length-1?'disabled':''}>Down</button><button class="text-link" data-pair="${e.id}">${e.group?'Edit superset':'Link superset'}</button></div>${e.group?`<p class="help">Alternate with ${esc(editor.entries.filter(x=>x.group===e.group&&x.id!==e.id).map(x=>ex(x.exerciseId)?.name).join(' + '))}</p>`:''}<div class="set-grid template-grid set-head"><span>TYPE</span><span>${unit.toUpperCase()}</span><span>REPS</span><span></span></div>${e.sets.map((s,i)=>`<div class="set-grid template-grid set-row"><button class="set-type" data-set-type="${e.id}/${s.id}" aria-label="${esc(exercise.name)} set ${i+1} type: ${s.type}">${s.type==='normal'?i+1:s.type==='warmup'?'W':'D'}</button><input type="text" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="24" aria-label="${esc(exercise.name)} set ${i+1} weight in ${unit}" data-set="${e.id}/${s.id}/weight" value="${toDisplay(s.weight,unit)}" placeholder="—"><input type="number" inputmode="numeric" min="1" max="1000" step="1" aria-label="${esc(exercise.name)} set ${i+1} reps" data-set="${e.id}/${s.id}/reps" value="${s.reps??''}" placeholder="—"><button class="remove" data-remove-set="${e.id}/${s.id}" aria-label="Remove ${esc(exercise.name)} set ${i+1}">×</button></div>`).join('')}<div class="exercise-actions"><button class="text-link" data-add-set="${e.id}">＋ Add set</button><button class="text-link" data-drop="${e.id}">＋ Drop set</button><button class="quiet danger" data-remove-entry="${e.id}" aria-label="Remove ${esc(exercise.name)} exercise">Remove</button></div></section>`}).join('')}${!editor.entries.length?'<div class="empty"><h2>Start with your first exercise.</h2><p>Browse by muscle group, then add the movements you want.</p></div>':''}<button class="secondary wide" data-action="add-exercise">＋ Add exercises</button><p class="note">Tap a set number to choose working, warmup, or drop set. Link exercises to alternate them as a superset.</p>${state.routines.some(r=>r.id===editor.id)?`<button class="quiet danger wide" data-delete-routine="${editor.id}">Delete routine</button>`:''}</section>`}

export function exerciseResults(state,query='',muscle='All',editor=null){const groups=[...new Set(state.exercises.map(e=>e.muscle||'Other'))].sort((a,b)=>a.localeCompare(b));const matches=state.exercises.filter(e=>(muscle==='All'||(e.muscle||'Other')===muscle)&&(e.name+' '+e.muscle).toLowerCase().includes(query.trim().toLowerCase()));return `<div class="chips muscle-chips" aria-label="Muscle groups">${['All',...groups].map(g=>`<button data-muscle="${esc(g)}" aria-pressed="${muscle===g}" class="${muscle===g?'active':''}">${esc(g)}</button>`).join('')}</div>${matches.length?groups.map(g=>{const list=matches.filter(e=>(e.muscle||'Other')===g);return list.length?`<details class="muscle-group" ${query||muscle!=='All'?'open':''}><summary>${esc(g)}<span>${list.length} exercises</span></summary>${list.map(e=>{const count=editor?.entries.filter(x=>x.exerciseId===e.id).length||0;return `<div class="exercise-choice-row"><button class="choice" data-add-ex="${e.id}" aria-label="Add ${esc(e.name)}"><span>${esc(e.name)}</span><small>${count?'Added '+count+' · tap to add another':'＋ Add exercise'}</small></button>${isCustomExercise(e)?`<button class="quiet edit-exercise-button" data-edit-exercise="${e.id}" data-edit-from="picker" aria-label="Edit ${esc(e.name)}">Edit</button>`:''}</div>`}).join('')}</details>`:''}).join(''):'<p class="empty">No exercises found. Try another muscle group or search.</p>'}`}
